async function reorderWatchlistItems(request, env, listId, accountId) {
  const { symbols } = await request.json();
  if (!Array.isArray(symbols)) return json({ error: 'symbols array required' }, 400);
  if (symbols.length > CONFIG.REORDER_MAX) return json({ error: 'Too many symbols (max ' + CONFIG.REORDER_MAX + ')' }, 400);
  const stmts = symbols.slice(0, CONFIG.REORDER_MAX).map((sym, i) =>
    env.DB.prepare('UPDATE watchlist_items SET sort_order = ? WHERE list_id = ? AND account_id = ? AND symbol = ?')
      .bind(i, listId, accountId, sanitizeWatchlistSymbol(sym))
  );
  if (stmts.length > 0) await env.DB.batch(stmts);
  return json({ success: true, count: stmts.length });
}

