async function listShareLinks(env, accountId) {
  const result = await env.DB.prepare('SELECT id, name, token, created, last_used, expires_at FROM share_tokens WHERE account_id = ? ORDER BY id DESC').bind(accountId).all();
  return json(result.results.map(r => ({ id: r.id, name: r.name || '', token: r.token, url: '/api/share/' + r.token, created: r.created, lastUsed: r.last_used || 0, expiresAt: r.expires_at || 0 })));
}
async function createShareLink(request, env, accountId) {
  const { name, ttlDays } = await request.json().catch(() => ({}));
  const token = generateToken();
  const expiresAt = (typeof ttlDays === 'number' && ttlDays > 0) ? Date.now() + ttlDays * 86400000 : 0;
  const r = await env.DB.prepare('INSERT INTO share_tokens (account_id, token, name, expires_at) VALUES (?, ?, ?, ?)').bind(accountId, token, String(name || '').slice(0, 200), expiresAt).run();
  return json({ id: r.meta.last_row_id, token, name: String(name || ''), url: '/api/share/' + token, created: Date.now(), expiresAt });
}
async function revokeShareLink(env, linkId, accountId) {
  const r = await env.DB.prepare('DELETE FROM share_tokens WHERE id = ? AND account_id = ?').bind(linkId, accountId).run();
  if (r.meta.changes === 0) return json({ error: 'Share link not found' }, 404);
  return json({ success: true });
}
async function getPublicShare(request, env, token) {
  if (!/^[a-f0-9]{32,256}$/.test(token)) return json({ error: 'Invalid token' }, 400);
  const row = await env.DB.prepare('SELECT id, account_id, name, expires_at FROM share_tokens WHERE token = ?').bind(token).first();
  if (!row) return json({ error: 'Share link not found or revoked' }, 404);
  if (row.expires_at > 0 && Date.now() > row.expires_at) return json({ error: 'Share link expired' }, 410);
  try { await env.DB.prepare('UPDATE share_tokens SET last_used = ? WHERE id = ?').bind(Date.now(), row.id).run(); } catch (_) {}
  const accountId = row.account_id;
  const acc = await env.DB.prepare('SELECT id, name FROM accounts WHERE id = ?').bind(accountId).first();
  if (!acc) return json({ error: 'Account not found' }, 404);
  const [trades, strategies, propFirms, watchlistLists, watchlistItems] = await Promise.all([
    env.DB.prepare('SELECT * FROM trades WHERE account_id = ? ORDER BY timestamp DESC').bind(accountId).all(),
    env.DB.prepare('SELECT id, name, checklist, notes, created FROM strategies WHERE account_id = ? ORDER BY id DESC').bind(accountId).all(),
    env.DB.prepare('SELECT * FROM prop_firms WHERE account_id = ? ORDER BY id DESC').bind(accountId).all(),
    env.DB.prepare('SELECT id, name, sort_order, created FROM watchlist_lists WHERE account_id = ? ORDER BY sort_order, id').bind(accountId).all(),
    env.DB.prepare('SELECT list_id, symbol, sort_order FROM watchlist_items WHERE account_id = ? ORDER BY list_id, sort_order').bind(accountId).all(),
  ]);
  const itemsByList = {};
  watchlistItems.results.forEach(it => {
    if (!itemsByList[it.list_id]) itemsByList[it.list_id] = [];
    itemsByList[it.list_id].push({ symbol: it.symbol, sort_order: it.sort_order });
  });
  return json({
    share: { name: row.name || '', accountName: acc.name, createdAt: row.created || Date.now(), expiresAt: row.expires_at || 0 },
    trades: trades.results.map(parseTrade),
    strategies: strategies.results.map(s => ({ id: s.id, name: s.name, checklist: s.checklist, notes: s.notes, created: s.created })),
    propFirms: propFirms.results.map(parsePropFirm),
    watchlists: watchlistLists.results.map(l => ({ id: l.id, name: l.name, sortOrder: l.sort_order, created: l.created, symbols: (itemsByList[l.id] || []).map(i => i.symbol) })),
  });
}

async function uploadImage(request, env, accountId) {
  try {
    const row = await env.DB.prepare('SELECT value FROM user_settings WHERE account_id = ? AND key = ?').bind(accountId, 'imgbb_apikey').first();
    const apiKey = row && row.value ? String(row.value).trim() : '';
    if (!apiKey) return json({ error: 'imgbb API key not set. Open Settings -> FX & Currency to add one.' }, 400);

    let base64Data = null;
    let fileName = 'upload.png';
    const contentType = (request.headers.get('Content-Type') || '').toLowerCase();

    if (contentType.includes('application/json')) {
      const body = await request.json().catch(() => ({}));
      if (!body || !body.image) return json({ error: 'Missing "image" field (base64 data)' }, 400);
      base64Data = String(body.image).replace(/^data:[^;]+;base64,/, '');
      if (body.name) fileName = String(body.name).slice(0, 100);
    } else if (contentType.includes('multipart/form-data')) {
      const formData = await request.formData();
      const file = formData.get('image');
      if (!file) return json({ error: 'Missing "image" file in form data' }, 400);
      const buf = await file.arrayBuffer();
      const bytes = new Uint8Array(buf);
      let binary = '';
      const chunkSize = 8192;
      for (let i = 0; i < bytes.length; i += chunkSize) {
        binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize));
      }
      base64Data = btoa(binary);
      if (file.name) fileName = String(file.name).slice(0, 100);
    } else {
      return json({ error: 'Content-Type must be multipart/form-data or application/json' }, 400);
    }

    if (!base64Data) return json({ error: 'Could not read image data' }, 400);
    if (base64Data.length > 32 * 1024 * 1024 * 1.37) return json({ error: 'Image too large (max 32 MB)' }, 413);

    const params = new URLSearchParams();
    params.set('key', apiKey);
    params.set('image', base64Data);
    params.set('name', fileName);

    const r = await fetch('https://api.imgbb.com/1/upload', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: params.toString(),
    });

    const j = await r.json().catch(() => null);
    if (!r.ok || !j || !j.success || !j.data || !j.data.url) {
      const errMsg = (j && j.error && j.error.message) || (r.status === 400 ? 'Bad request — check your imgbb API key' : 'imgbb upload failed (HTTP ' + r.status + ')');
      return json({ error: errMsg }, 502);
    }

    return json({ success: true, url: j.data.url, viewerUrl: j.data.url_viewer || null, thumbUrl: (j.data.thumb && j.data.thumb.url) || null, mediumUrl: (j.data.medium && j.data.medium.url) || null, displayUrl: j.data.display_url || j.data.url, width: j.data.width || null, height: j.data.height || null, size: j.data.size || null, id: j.data.id || null });
  } catch (e) {
    return json({ error: 'Upload failed: ' + (e && e.message || 'unknown error') }, 500);
  }
}

function json(data, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json', ...extraHeaders } });
}

